@app.route('/')
def home(): return HTML
@app.route('/api/v1/posts', methods=['GET'])
def get_posts(): return jsonify(feed_algo(POSTS))
@app.route('/api/v1/posts', methods=['POST'])
def create_post():
    d=request.json or {}; p={"post_id":str(uuid.uuid4()),"author_id":d.get("author_name","أنت"),"author_name":d.get("author_name","أنت"),"author_avatar":d.get("author_avatar","https://i.pravatar.cc/150?u=me"),"content":d.get("content",""),"media_url":d.get("media_url",""),"media_type":d.get("media_type","text"),"kind":d.get("kind","post"),"likes_count":0,"comments_count":0,"shares_count":0,"liked":False,"created_at":""}; POSTS.append(p); COMMENTS[p["post_id"]]=[]; return jsonify(p)
@app.route('/api/v1/posts/<pid>/like', methods=['POST'])
def like_post(pid):
    for p in POSTS:
        if p["post_id"]==pid:
            p["liked"]=not p["liked"]; p["likes_count"]+=1 if p["liked"] else -1
            if p["liked"]: INTERACTIONS[p["author_id"]]=INTERACTIONS.get(p["author_id"],0)+1
            return jsonify(p)
    return jsonify({"error":"not found"}),404
@app.route('/api/v1/posts/<pid>/share', methods=['POST'])
def share_post(pid):
    for p in POSTS:
        if p["post_id"]==pid: p["shares_count"]=p.get("shares_count",0)+1; return jsonify(p)
    return jsonify({"error":"not found"}),404
@app.route('/api/v1/posts/<pid>/comments', methods=['GET'])
def get_comments(pid): return jsonify(COMMENTS.get(pid,[]))
@app.route('/api/v1/posts/<pid>/comment', methods=['POST'])
def comment_post(pid):
    d=request.json or {}
    for p in POSTS:
        if p["post_id"]==pid: p["comments_count"]+=1; INTERACTIONS[p["author_id"]]=INTERACTIONS.get(p["author_id"],0)+2; COMMENTS.setdefault(pid,[]).append({"author":d.get("author","أنت"),"content":d.get("content","")}); return jsonify({"ok":True})
    return jsonify({"error":"not found"}),404
@app.route('/api/v1/suggest', methods=['GET'])
def get_suggest(): return jsonify(suggest_algo())
@app.route('/api/v1/friends/add', methods=['POST'])
def add_friend():
    d=request.json or {}; FRIENDS.add(d.get("name")); return jsonify({"ok":True})
@app.route('/api/v1/chats', methods=['GET'])
def get_chats(): return jsonify(list(CHATS.values()))
@app.route('/api/v1/chats', methods=['POST'])
def create_chat():
    d=request.json or {}; cid=str(uuid.uuid4()); CHATS[cid]={"chat_id":cid,"name":d.get("name","محادثة"),"avatar":d.get("avatar",f"https://i.pravatar.cc/150?u={cid}"),"last_message":""}; return jsonify(CHATS[cid])
@app.route('/api/v1/chats/<cid>/messages', methods=['GET'])
def get_messages(cid): return jsonify(MESSAGES.get(cid,[]))
@app.route('/api/v1/chats/<cid>/messages', methods=['POST'])
def send_message(cid):
    d=request.json or {}; m={"message_id":str(uuid.uuid4()),"chat_id":cid,"sender_id":d.get("sender_id","me"),"content":d.get("content","")}; MESSAGES.setdefault(cid,[]).append(m)
    if cid in CHATS: CHATS[cid]["last_message"]=d.get("content","")
    return jsonify(m)
@app.route('/api/v1/security/privacy-score', methods=['GET'])
def privacy(): return jsonify(privacy_algo(SETTINGS["demo"]))
@app.route('/api/v1/settings/toggle', methods=['POST'])
def toggle_setting():
    d=request.json or {}; SETTINGS["demo"][d.get("key")]=d.get("value"); return jsonify(SETTINGS["demo"])
@app.route('/api/v1/settings/fix-all', methods=['POST'])
def fix_all():
    SETTINGS["demo"]={"two_factor":True,"active_status":False,"app_lock":1,"default_audience":"FRIENDS"}; return jsonify(SETTINGS["demo"])
if __name__=='__main__': app.run(host='0.0.0.0', port=int(os.environ.get('PORT',5000)))
